<?php
declare(strict_types=1);namespace App\Http\Controllers\Administration;use App\Application\Projects\ProjectMatchingConfiguration;use App\Domain\Identity\CoreIdentity;use App\Models\PortalSetting;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
final class ProjectMatchingConfigurationController{public function edit(ProjectMatchingConfiguration $c):View{return view('administration.project-matching',['configuration'=>$c->get()]);}public function update(Request $r):RedirectResponse{/** @var CoreIdentity $i */$i=$r->attributes->get('dg_identity');$d=$r->validate(['page_title'=>['required','string','max:180'],'page_intro'=>['required','string','max:700'],'candidate_pool'=>['required','integer','min:20','max:500'],'max_results'=>['required','integer','min:3','max:60'],'max_reasons'=>['required','integer','min:1','max:8'],'location_context'=>['nullable','boolean'],'participation_context'=>['nullable','boolean']]);$d['location_context']=$r->boolean('location_context');$d['participation_context']=$r->boolean('participation_context');PortalSetting::query()->updateOrCreate(['key'=>ProjectMatchingConfiguration::KEY],['value'=>$d,'updated_by_core_reference'=>$i->reference]);return back()->with('status','Configuration CAP‑015 enregistrée.');}}
